    idx = 0
    t = int(lines[idx])
    idx += 1

    results = []

    for _ in range(t):
        n = int(lines[idx])
        idx += 1
        a = list(map(int, lines[idx].split()))
        idx += 1

        # Check if configuration is valid given an array
        def check(arr):
            ops = 0
            for i in range(n):
                if arr[i] < ops:
                    return False
                if i == n - 1:
                    if arr[i] - ops != 0:
                        return False
                else:
                    ops = arr[i] - ops
                    if ops < 0:
                        return False
            return True

        # Check without any swap
        if check(a):
            results.append("YES")
            continue

        # Find valid swapping position
        found = False
        for i in range(n - 1):
            # Try swapping a[i] and a[i+1]
            b = a[:]
            b[i], b[i+1] = b[i+1], b[i]
            if check(b):
                results.append("YES")
                found = True
                break

        if not found:
            results.append("NO")

    return '\n'.join(results)

