    n, c = map(int, lines[0].split())

    if n == 0:
        return ""

    constraints = []
    for i in range(1, len(lines)):
        line = lines[i].strip()
        if not line:
            continue
        parts = line.split()
        if len(parts) >= 3:
            ai, bi = int(parts[0]), int(parts[1])
            direction = parts[2]
            constraints.append((ai, bi, direction))

    # Build graph and check structural validity
    # count how many "left" and "right" relationships each node has
    node_params = {i: {'left': 0, 'right': 0} for i in range(1, n + 1)}

    for ai, bi, direction in constraints:
        if direction == 'LEFT':
            # bi in ai's left subtree
            if node_params[bi]['left']:
                # bi cannot be in multiple left subtrees
                return "IMPOSSIBLE\n"
            node_params[bi]['left'] = 1
            # ai has a left child relationship
            node_params[ai]['right'] = node_params[ai].get('right', 0) + 1
        else:  # RIGHT
            # bi in ai's right subtree  
            if node_params[bi]['right']:
                return "IMPOSSIBLE\n"
            node_params[bi]['right'] = 1
            node_params[ai]['left'] = node_params[ai].get('left', 0) + 1

    # Build graph for topological sort
    graph = {i: [] for i in range(1, n + 1)}
    in_degree = {i: 0 for i in range(1, n + 1)}

    for ai, bi, direction in constraints:
        if direction == 'LEFT':
            edge = (bi, ai)  # bi before ai
        else:  # RIGHT
            edge = (ai, bi)  # ai before bi

        graph[edge[0]].append(edge[1])
        in_degree[edge[1]] += 1

    # Topological sort (Kahn's algorithm)
    queue = [i for i in range(1, n + 1) if in_degree[i] == 0]
    result = []
    processed = 0

    while queue:
        node = queue.pop(0)
        result.append(node)
        processed += 1
        for neighbor in graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    if processed != n:
        return "IMPOSSIBLE\n"

    # Check if node 1 (root) is in result at some position
    # and output the topological order
    return ' '.join(map(str, result)) + '\n'

