def find_rectangular_regions(n, m, grid):
    """Find rectangular regions that cover all free cells."""
    visited = [[False] * m for _ in range(n)]
    rectangle_regions = []

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    for i in range(n):
        for j in range(m):
            if not visited[i][j] and grid[i][j] == '.':
                # Find all connected free cells starting from (i, j)
                connected = []
                queue = deque([(i, j)])
                visited[i][j] = True
                connected.append((i, j))

                while queue:
                    r, c = queue.popleft()
                    for dr, dc in directions:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < n and 0 <= nc < m and not visited[nr][nc] and grid[nr][nc] == '.':
                            visited[nr][nc] = True
                            connected.append((nr, nc))
