                    # Find bounding box
                    min_r = min(r for r, c in connected)
                    max_r = max(r for r, c in connected)
                    min_c = min(c for r, c in connected)
                    max_c = max(c for r, c in connected)
                    rectangle_regions.append({
                        'cells': set(connected),
                        'rows': range(min_r, max_r + 1),
                        'cols': range(min_c, max_c + 1)
                    })

    return rectangle_regions

def is_rectangle(cells):
    """Check if a set of cells forms a rectangle."""
    if not cells:
        return False

    min_r = min(r for r, c in cells)
    max_r = max(r for r, c in cells)
    min_c = min(c for r, c in cells)
    max_c = max(c for r, c in cells)

    expected_count = (max_r - min_r + 1) * (max_c - min_c + 1)
    return len(cells) == expected_count and all(
        min_r <= r <= max_r and min_c <= c <= max_c for r, c in cells
    )

