def is_geometric(seq):
    """Check if a sequence is a geometric progression."""
    n = len(seq)
    if n <= 1:
        return True

    # All zeros is a valid Gaussian progression
    if all(x == 0 for x in seq):
        return True

    # Handle zeros specially
    first_zero = False
    first_nonzero = False
    nonzero_ratio = None

    for i in range(n):
        if seq[i] != 0:
            first_zero = True
            first_nonzero = True
            if i == 1:
                nonzero_ratio = seq[i] / seq[0]
                break

    # If starts with zero but not all zeros, check that the first non-zero follows the pattern
    # But actually, simplest: just use two consecutive non-zero elements or first two

    if seq[0] == 0:
        if seq[1] == 0:
            # First two are zero, check entire sequence is zero
            return all(x == 0 for x in seq)
        else:
            # 0 followed by non-zero - must check if it's GP
            # Then seq[1] must be x, seq[2] = x*ratio, etc
            # But after first zero, ratio is undefined, so second to third gives ratio
            if seq[1] * seq[1] == seq[2] * seq[0]:
                # If 0, non-zero, then ratio is seq[2]/seq[1] if seq[2] != 0
                if seq[2] == 0:
                    # 0, non-zero, 0 - can't be GP
                    return False
                else:
                    ratio = seq[2] / seq[1]
                    for i in range(3, n):
                        if seq[i] != seq[i-1] * ratio:
                            return False
                    return True
            else:
                # 0, non-zero, 0 or inconsistent - but this should not be a GP
                # Handle carefully: 0, a, b where a*0 != b*0 => can't form GP
                for i in range(3, n):
                    if seq[i] != seq[i-1] * (seq[2] / seq[1]):
                        return False
                return True
    else:
        # seq[0] is non-zero, use ratio from first two
        ratio = seq[1] / seq[0]
        for i in range(2, n):
            if seq[i] != seq[i - 1] * ratio:
                return False
        return True


