from itertools import combinations

def dist(p1, p2):
    """Euclidean distance between two 3D points"""
    return np.linalg.norm(np.array(p1) - np.array(p2))

def gauss_elim(A, b):
    """Solve linear system using Gaussian elimination"""
    n = len(A)
    M = [row[:] + [b[i]] for i, row in enumerate(A)]

    pivot_row = 0
    for col in range(n):
        max_row = pivot_row
        for row in range(pivot_row + 1, n):
            if abs(M[row][col] - M[max_row][col]) > abs(M[max_row][col]):
                max_row = row

        M[pivot_row], M[max_row] = M[max_row], M[pivot_row]

        if abs(M[pivot_row][col]) < 1e-12:
            continue

        for row in range(pivot_row + 1, n):
            c = M[row][col] / M[pivot_row][col]
            M[row][col:] = [M[row][j] - c * M[pivot_row][j] for j in range(col, n + 1)]

        pivot_row += 1

    return [M[i][n] / M[i][i] if M[i][i] > 1e-12 else 0.0 for i in range(n)]

