def check_complete_full_binary_tree(n, adj, nodes):
    """
    Check if current graph (after removing vertex v, reconstructing correctly)
    forms a complete full binary tree.

    Key properties:
    - num_nodes = 2^n - 1
    - All leaves at same depth
    - Internal nodes have exactly 2 children
    - Root has degree 2 (or 1 for small cases)
    """
    if len(nodes) != 2**n - 1:
        return False

    if len(nodes) == 1:
        return len(adj) == 0

    try:
        # Find root (node with degree 1 for n=2, or check structure)
        candidates = []
        for r in nodes:
            # Potential root: degree 1 (for n=2) or degree 2 (for larger n)
            candidates.append(r)

        # BFS depth check
        depths = {}
        max_depth = -1

        for start in candidates:
            queue = deque([start])
            depths[start] = 0
            max_depth = 0

            while queue:
                curr = queue.popleft()
                max_depth = max(max_depth, depths[curr])

                for neighbor in adj.get(curr, []):
                    if neighbor not in depths:
                        depths[neighbor] = depths[curr] + 1
                        queue.append(neighbor)

        # All internal nodes must have degree 2
        for v in nodes:
            d = len(adj[v])
            # Leaves have degree 1, internal have degree 3 (root has degree 2)
            if d > 3:
                return False

        # Check all depths in tree
        return max_depth == n - 1 or max_depth == 0
    except Exception:
        return False

