    # Case n = 1: any single integer
    if n == 1:
        return str(r - l + 1)

    # Case n = 2: any pair of distinct integers
    if n == 2:
        return str((r - l + 1) * (r - l))

    # Case n >= 3
    ans = 0
    # For n=3, need d^2 <= r, so d <= sqrt(r)
    limit = int(r**(1/(n-1))) + 2

    for q in range(1, limit):
        q_pow = q ** (n - 1)
        if q_pow > r:
            break

        for p in range(1, limit):
            if p == 1:
                p_pow = 1
            else:
                p_pow = p ** (n - 1)

            if p_pow > r:
                if p_pow < 0 or (p // q == 1 and q < p):
                    pass
                break

            if p == q:
                continue

            if gcd(p, q) == 1:
                # a_1 = k * q^(n-1)
                # a_n = k * p^(n-1)
                # Both must be in [l, r]

                # a_1 >= l => k * q_pow >= l
                # a_n >= l => k * p_pow >= l

                k_min_a1 = (l + q_pow - 1) // q_pow
                k_min_an = (l + p_pow - 1) // p_pow

                k_min = max(k_min_a1, k_min_an)

                # a_1 <= r => k * q_pow <= r
                # a_n <= r => k * p_pow <= r

                k_max_a1 = r // q_pow
                k_max_an = r // p_pow

                k_max = min(k_max_a1, k_max_an)

                if k_max >= k_min:
                    ans += k_max - k_min + 1

    return str(ans)

