    depth = [0] * (n + 1)
    parent = [0] * (n + 1)
    found_cycle = []
    found = False

    def dfs(u, p, d):
        nonlocal found
        visited[u] = True
        depth[u] = d
        parent[u] = p

        for v in adj[u]:
            if v == p:
                continue
            if visited[v]:
                # Back edge found
                if depth[v] < depth[u]:
                    # v is ancestor of u - we have a cycle
                    cycle = []
                    curr = u
                    cycle.append(curr)
                    curr = parent[curr]
                    while curr != v:
                        cycle.append(curr)
                        curr = parent[curr]
                    cycle.append(v)
                    found = True
                    return cycle
            else:
                if dfs(v, u, d + 1):
                    return found_cycle if found else []
        return None

