    # Find finish position
    finish = None
    for i in range(len(grid)):
        for j in range(len(grid[i])):
            if grid[i][j] == 'F':
                finish = (i, j)
                break
        if finish:
            break

    if finish is None:
        return ""

    # Build direction mappings with swaps
    # U=(-1,0), D=(1,0), L=(0,-1), R=(0,1)
    direction_moves = {
        'U': (-1, 0),
        'D': (1, 0),
        'L': (0, -1),
        'R': (0, 1)
    }

