        direction_moves['L'] = (0, 1)  # L now means right
        direction_moves['R'] = (0, -1)  # R now means left

    if swapUD:
        direction_moves['U'] = (1, 0)  # U now means down  
        direction_moves['D'] = (-1, 0)  # D now means up

    # BFS to find shortest path from (0,0) to finish
    start = (0, 0)
    queue = deque([(start, "")])
    visited = set([start])

    result_path = ""

    while queue:
        (r, c), path = queue.popleft()

        if (r, c) == finish:
            result_path = path
