    def can_win(curr_a, curr_b):
        """
        Returns True if the current player (whose turn it is) can win from state (curr_a, curr_b).
        A player wins if they can make a move that leaves the opponent in a losing position.
        """
        if (curr_a, curr_b) in memo:
            return memo[(curr_a, curr_b)]

        # If current state already meets the losing threshold, the previous player lost
        if curr_a ** curr_b >= n:
            return True

        # Check if increasing boxes (a+1, b) would exceed threshold immediately
        exceeds_a = (curr_a + 1) ** curr_b >= n
        # Check if increasing items (a, b+1) would exceed threshold immediately  
        exceeds_b = curr_a ** (curr_b + 1) >= n

        # If both moves immediately lose, this player has no valid moves and loses
        if exceeds_a and exceeds_b:
            memo[(curr_a, curr_b)] = False
            return False

        # A winning move is one that leads to a losing state for the opponent
        can_force_opponent_loss = False

        # Try increasing boxes
        if not exceeds_a:
            if not can_win(curr_a + 1, curr_b):
                can_force_opponent_loss = True

        # Try increasing items
        if not exceeds_b:
            if not can_win(curr_a, curr_b + 1):
                can_force_opponent_loss = True

        memo[(curr_a, curr_b)] = can_force_opponent_loss
        return can_force_opponent_loss

