    memo = {}

    def count_subspaces(k):
        if k == 0:
            return 1
        if k == 1:
            return 2

        if k in memo:
            return memo[k]

        m = k.bit_length()

        # Check if k = 2^m - 1 (all bits 1 from position 0 to m-1)
        max_range = (1 << m) - 1

        if k == max_range:
            # Count all subspaces in m-dimensional space over GF(2)
            # This uses sum of Gaussian binomial coefficients
            total = 0
            for d in range(m + 1):
                # Gaussian binomial C(m, d)_2
                numerator = 1
                denominator = 1
                for i in range(d):
                    numerator = (numerator * (pow(2, m - i, MOD) - 1)) % MOD
                    denominator = (denominator * (pow(2, i + 1, MOD) - 1)) % MOD
                coeff = (numerator * pow(denominator, MOD - 2, MOD)) % MOD
                total = (total + coeff) % MOD
            memo[k] = total
            return total
        else:
            # k < 2^m - 1, find the position of the least significant '1'
            # after the most significant bit to determine decomposition
            # Find if k has all trailing zeros up to some position
            temp = k
            trailing_zeros = 0
            while (temp & 1) == 0 and temp > 0:
                trailing_zeros += 1
                temp >>= 1

            # If k = 2^m, decompose as: count(2^m - 1) + count(0)
            highest_bit = 1 << (m - 1)

            if k == highest_bit:
                result = (count_subspaces(highest_bit - 1) + 
                          count_subspaces(highest_bit - highest_bit)) % MOD
            elif k == highest_bit + (highest_bit - 1):  # 2^m + 2^m - 1 = 2^(m+1) - 1
                # This won't happen within bit_length m
                pass
            else:
                # General case: decompose by highest bit
                rest = k - highest_bit
                result = (count_subspaces(highest_bit - 1) + 
                          k_subspaces(rest)) % MOD

