            sets_str = format_sets_for_output(a, b, win_a, win_b)
            return score + "\n" + sets_str + " "

    return "Impossible\n"

def can_form_match(a, b, win_a, win_b):
    """Check if it's possible to form this match score."""
    num_sets = win_a + win_b

    if num_sets == 0:
        return a == 0 and b == 0

    # Check if valid decomposition exists
    def backtrack(rem_a, rem_b, k_left):
        if k_left == 0:
            return rem_a == 0 and rem_b == 0

        for score_a in range(1, min(a + 1, 201)):
            for score_b in range(1, min(b + 1, 201)):
                if score_a == score_b:
                    continue
                if score_a < 25 or score_a < 25:
                    continue
                if max(score_a, score_b) - min(score_a, score_b) < 2:
                    continue

                next_a = rem_a - score_a
                next_b = rem_b - score_b
                if next_a < 0 or next_b < 0:
                    continue

                if backtrack(next_a, next_b, k_left - 1):
                    return True
        return False

    return backtrack(a, b, num_sets)

def format_sets_for_output(a, b, win_a, win_b):
    """Actually compute and format valid set scores."""
    num_sets = win_a + win_b

    # Use simple backtracking to find ANY valid decomposition
    def backtrack(rem_a, rem_b, depth, sets):
        if depth == num_sets:
            if rem_a == 0 and rem_b == 0:
                return sets.sort(), True
            return sets, False

        # Try all valid scores
        for score_a in range(1, min(rem_a + 1, 201)):
            for score_b in range(1, min(rem_b + 1, 201)):
                if score_a < 25:
                    continue
                if score_a - score_b < 2 or score_b - score_a < 2:
                    continue

                rest = backtrack(rem_a - score_a, rem_b - score_b, depth + 1, sets + [(score_a, score_b)])
                if rest[1]:
                    return rest

    result = backtrack(a, b, 0, [])
    return result


