def check_matching_decomposition(target_a, target_b, num_sets, target_win_a, target_win_b):
    """Check if (a,b) can be split into num_sets with correct winners."""
    if num_sets == 0:
        return target_a == 0 and target_b == 0, ()

    def search(rem_a, rem_b, depth, a_wins, b_wins, decomposition):
        if depth == num_sets:
            if rem_a != 0 or rem_b != 0 or a_wins != target_win_a or b_wins != target_win_b:
                return False, ()
            return True, tuple(decomposition)

        # Try all valid scores for this set
        for wa in range(1, min(target_a + 1, 201)):
            for wb in range(1, min(target_b + 1, 201)):
                # Check if score is valid
                if wa == wb:
                    continue
                if min(wa, wb) < 15:
                    continue
                lead = abs(wa - wb)
                if lead < 2:
                    continue

                # Check winner and if we have capacity
                winner_a = 1 if wa > wb else 0
                winner_b = 1 if wb > wa else 0
                if winner_b == 1 and winner_a == 1:
                    continue

                if a_wins < target_win_a and winner_a == 1:
                    success, rest = search(rem_a - wa, rem_b - wb, depth + 1, a_wins + 1, b_wins, 
                                          decomposition + [(wa, wb)])
                    if success:
                        return True, rest
                elif winner_a == 0 and b_wins < target_win_b:
                    success, rest = search(rem_a - wa, rem_b - wb, depth + 1, a_wins, b_wins + 1,
                                          decomposition + [(wa, wb)])
                    if success:
                        return True, rest

        return False, ()

    success, decomp = search(target_a, target_b, 0, 0, 0, [])
    return success, decomp
